        if (multiText.length === 0) {
            block.inlines = [{ text: '' }];
            blocks.push(block);
        }
        else {
            while (multiText.length > 0) {
                block.inlines = [{ text: multiText[0] }];
                blocks.push(block);
                multiText.splice(0, 1);
            }
        }
        return blocks;
